import numpy as np
from sim import Sim
for desc,ctrl in [('zero',None),('home', 'home')]:
    sim=Sim()
    if ctrl=='home':
        c=sim.home_ctrl()
    elif ctrl is None:
        c=np.zeros(sim.model.nu)
    for _ in range(600):
        if c is not None:
            sim.data.ctrl[:] = c
        sim.step(1)
    print(desc,'pelvis',sim.pelvis_position(),'d',sim.distance_to_target(),'z',sim.pelvis_position()[2],'torso',sim.torso_up())
