/bin/bash -lc "python - <<'PY'
import numpy as np
from sim import Sim
h=Sim().home_ctrl()

# test scaling of constant controller and maybe forward lean torso
for s in [1,2,3,4,5,6]:
    sim=Sim();
    ctrl=h*s
    # clip to legal by model? use 10% margin
    sim.data.ctrl[:] = np.clip(ctrl,[-200,-200,-200,-300,-40,-200,-200,-200,-300,-40,-200,-40,-40,-18,-18,-40,-40,-18,-18],[200,200,200,300,40,200,200,200,300,40,200,40,40,18,18,40,40,18,18])
    for _ in range(400):
        sim.step(1)
    p=sim.pelvis_position();
    print('scale',s,'x',p[0],'z',p[2],'torso',sim.torso_up(),'d',sim.distance_to_target())

# forward lean by torso and hip pitch offsets
for off in [0, 0.2, -0.2, 0.4]:
    sim=Sim();
    ctrl=h.copy(); ctrl[10]=off  # torso actuator
    sim.data.ctrl[:] = np.clip(ctrl,[-200,-200,-200,-300,-40,-200,-200,-200,-300,-40,-200,-40,-40,-18,-18,-40,-40,-18,-18],[200,200,200,300,40,200,200,200,300,40,200,40,40,18,18,40,40,18,18])
    for _ in range(400): sim.step(1)
    p=sim.pelvis_position(); print('torso_off',off,'x',p[0],p[2],sim.torso_up(),sim.distance_to_target())
PY"

